package com.javamentor.agent;

import com.javamentor.model.AuditReport;
import com.javamentor.model.MentorResponse;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.regex.Pattern;

/**
 * Autonomous Critic & Auditor Agent.
 * Inspects responses generated by the Mentor Agent against the 100-mark rubric:
 * 1. Three-Stage Output Model Compliance (30 Marks)
 * 2. JVM & Engineering Depth (25 Marks)
 * 3. Zero-Truncation Enforcement (15 Marks)
 * 4. Test Suite Execution Harness (15 Marks)
 * 5. Formatting & Code Quality (15 Marks)
 */
public class AuditorAgent implements Agent {

    // Forbidden truncation patterns that violate the zero-truncation requirement
    private static final String[] TRUNCATION_PATTERNS = {
            "// logic goes here",
            "// your code here",
            "// implement here",
            "// add your code here",
            "// TODO",
            "/* TODO */",
            "/* logic goes here */",
            "// add implementation",
            "// rest of implementation"
    };

    @Override
    public String getName() {
        return "Auditor & Critic Agent";
    }

    @Override
    public String getRole() {
        return "Pedagogical Inspector & Rubric Verification Engine";
    }

    /**
     * Inspects and scores a MentorResponse.
     */
    public AuditReport audit(MentorResponse response) {
        List<String> feedback = new ArrayList<>();
        int score = 0;

        String p1 = response.getPhase1Conceptual();
        String p2 = response.getPhase2Algorithmic();
        String p3 = response.getPhase3Code();

        // 1. Check Phase 1: Conceptual Breakdown (Max 30 marks)
        boolean phase1Valid = false;
        if (p1 != null && p1.length() >= 60) {
            score += 15; // presence and basic length
            String lowerP1 = p1.toLowerCase(Locale.ROOT);
            boolean hasJvm = lowerP1.contains("jvm") || lowerP1.contains("heap") || lowerP1.contains("stack")
                    || lowerP1.contains("garbage") || lowerP1.contains("memory") || lowerP1.contains("bytecode")
                    || lowerP1.contains("runtime");
            boolean hasContext = lowerP1.contains("production") || lowerP1.contains("anti-pattern")
                    || lowerP1.contains("advantage") || lowerP1.contains("industry");

            if (hasJvm) {
                score += 10;
            } else {
                feedback.add("Phase 1 lacks explicit JVM runtime mechanics (heap/stack, GC, bytecode, or memory model).");
            }

            if (hasContext) {
                score += 5;
            } else {
                feedback.add("Phase 1 lacks industrial real-world context versus known anti-patterns.");
            }
            phase1Valid = true;
        } else {
            feedback.add("Phase 1 (Conceptual Breakdown) is missing or insufficient.");
        }

        // 2. Check Phase 2: Algorithmic Logic & Architectural Blueprint (Max 25 marks)
        boolean phase2Valid = false;
        if (p2 != null && p2.length() >= 40) {
            score += 10;
            String lowerP2 = p2.toLowerCase(Locale.ROOT);
            boolean hasSteps = lowerP2.contains("1.") || lowerP2.contains("step") || lowerP2.contains("algorithm")
                    || lowerP2.contains("recipe") || lowerP2.contains("blueprint");
            boolean hasComplexity = lowerP2.contains("o(") || lowerP2.contains("time complexity")
                    || lowerP2.contains("space complexity") || lowerP2.contains("complexity");
            boolean hasEdgeCases = lowerP2.contains("edge") || lowerP2.contains("null")
                    || lowerP2.contains("exception") || lowerP2.contains("concurrency");

            if (hasSteps) {
                score += 5;
            } else {
                feedback.add("Phase 2 should provide structured step-by-step numbered logic or pseudocode.");
            }

            if (hasComplexity) {
                score += 5;
            } else {
                feedback.add("Phase 2 lacks formal Big-O Time and Space Complexity annotations.");
            }

            if (hasEdgeCases) {
                score += 5;
            } else {
                feedback.add("Phase 2 should explicitly address edge cases (null-safety, boundaries, exceptions).");
            }
            phase2Valid = true;
        } else {
            feedback.add("Phase 2 (Algorithmic Blueprint) is missing or insufficient.");
        }

        // 3. Check Phase 3: Zero Truncation Rule (Max 15 marks)
        boolean zeroTruncation = true;
        if (p3 != null) {
            for (String pattern : TRUNCATION_PATTERNS) {
                if (p3.toLowerCase(Locale.ROOT).contains(pattern.toLowerCase(Locale.ROOT))) {
                    zeroTruncation = false;
                    feedback.add("Zero Truncation Violation: Code contains forbidden placeholder: '" + pattern + "'");
                    break;
                }
            }
            if (zeroTruncation && (p3.contains("{ ... }") || p3.contains("{...}") || p3.matches("(?s).*\\n\\s*\\.{3}\\s*(\\n|$).*"))) {
                zeroTruncation = false;
                feedback.add("Zero Truncation Violation: Code contains ellipsis placeholder '...'");
            }

            if (zeroTruncation) {
                score += 15;
            }
        } else {
            zeroTruncation = false;
            feedback.add("Phase 3 code block is empty.");
        }

        // 4. Check Phase 3: Runnable Code and Integrated Test Scenarios (Max 20 marks)
        boolean phase3Valid = false;
        boolean hasTestScenarios = false;
        if (p3 != null && p3.length() >= 80) {
            boolean hasClass = p3.contains("class ");
            boolean hasMain = p3.contains("public static void main");
            boolean hasPrint = p3.contains("System.out.print");

            if (hasClass && hasMain) {
                score += 10;
                phase3Valid = true;
            } else {
                feedback.add("Phase 3 must contain a fully compilable public class with public static void main.");
            }

            // Check for at least two test scenarios
            int testOccurrences = countOccurrences(p3.toLowerCase(Locale.ROOT), "test")
                    + countOccurrences(p3.toLowerCase(Locale.ROOT), "scenario")
                    + countOccurrences(p3.toLowerCase(Locale.ROOT), "case");

            if (testOccurrences >= 2 || (hasPrint && countOccurrences(p3, "System.out.print") >= 2)) {
                score += 10;
                hasTestScenarios = true;
            } else {
                score += 5;
                feedback.add("Phase 3 main() should demonstrate at least two distinct test scenarios.");
            }
        } else {
            feedback.add("Phase 3 code is missing or incomplete.");
        }

        // 5. General Structure & Formatting (Max 10 marks)
        if (phase1Valid && phase2Valid && phase3Valid) {
            score += 10;
        }

        // Clamp score between 0 and 100
        score = Math.min(100, Math.max(0, score));

        boolean passed = score >= 75 && zeroTruncation && phase1Valid && phase2Valid && phase3Valid;
        return new AuditReport(passed, score, phase1Valid, phase2Valid, phase3Valid, zeroTruncation, hasTestScenarios, feedback);
    }

    private int countOccurrences(String text, String token) {
        if (text == null || token == null || token.isEmpty()) {
            return 0;
        }
        int count = 0;
        int idx = 0;
        while ((idx = text.indexOf(token, idx)) != -1) {
            count++;
            idx += token.length();
        }
        return count;
    }
}
